mapper.select:
SELECT f.id, f.teacher_id, u.real_name AS teacher_name, ti.title, (SELECT GROUP_CONCAT(DISTINCT ts2.course_name ORDER BY ts2.course_name SEPARATOR '、') FROM teacher_semester ts2 WHERE ts2.teacher_id = f.teacher_id AND ts2.semester_id = f.semester_id AND ts2.course_name IS NOT NULL AND ts2.course_name != '') AS course_names, f.semester_id, s.semester_name, f.reflection, f.improvement_plan, f.update_time, (SELECT ROUND(AVG(r.total_score), 2) FROM eval_record r WHERE r.teacher_id = f.teacher_id AND r.semester_id = f.semester_id AND r.status = 1) AS avg_score FROM teacher_feedback f JOIN sys_user u ON u.id = f.teacher_id JOIN semester s ON s.id = f.semester_id LEFT JOIN teacher_info ti ON ti.user_id = f.teacher_id
AND f.teacher_id = #{teacherId}
AND f.semester_id = #{semesterId}
ORDER BY f.update_time DESC
